gh api graphql -f query='
query {
  repository(owner: "ZimmermannAU", name: "zimmermann-pwa") {
    pullRequest(number: 80) {
      reviewThreads(first: 50) {
        nodes {
          isResolved
          path
          line
          comments(first: 5) { nodes { author { login } body createdAt } }
        }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes[] | {path, line, isResolved, firstComment: .comments.nodes[0].body[0:120]}'

gh api graphql -f query='
query {
  repository(owner: "ZimmermannAU", name: "zimmermann-pwa") {
    pullRequest(number: 80) {
      reviewThreads(first: 50) {
        nodes {
          isResolved
          path
          line
          comments(first: 10) { nodes { author { login } body createdAt } }
        }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes[] | select(.path == "lighthouserc.js") | .comments.nodes[] | {author: .author.login, createdAt, body}'

